  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.</p>": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">नया पेज व्हाइटबोर्ड के रूप में खुलेगा। पूरे कैनवास पर स्वतंत्र रूप से ड्रॉ करें और शेप, स्टिकी नोट व कनेक्टर जोड़ें।</p>",
  "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">Cancel</button>": "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">रद्द करें</button>",
