  "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">Board Already Exists</h3>": "<h3 style=\"margin:0 0 6px;font-size:16px;color:var(--text);\">बोर्ड पहले से मौजूद है</h3>",
  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">There is already an open board ": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">पहले से एक बोर्ड खुला है ",
