  "<div class=\"bulk-builder-empty-title\">No panel connection</div>": "<div class=\"bulk-builder-empty-title\">पैनल कनेक्शन नहीं है</div>",
  "<div class=\"bulk-builder-empty-sub\">The product library is available when the editor is opened with a design from the panel. In this tab, you can use the Excel or AI source.</div>": "<div class=\"bulk-builder-empty-sub\">एडिटर को पैनल के डिज़ाइन से खोलने पर प्रोडक्ट लाइब्रेरी उपलब्ध होती है। इस टैब में Excel या AI स्रोत का उपयोग कर सकते हैं।</div>",
