  "No panel connection.": "पैनल कनेक्शन नहीं है.",
  "Select an object on … assign <strong>Design Field</strong> (e.g. title, image, price) from the right panel. Then come back here; let AI or Excel multiply those fields.</div>": "किसी ऑब्जेक्ट का चयन करें… दाएँ पैनल में <strong>डिज़ाइन फ़ील्ड</strong> (जैसे शीर्षक, छवि या कीमत) असाइन करें। फिर यहाँ लौटें और AI या Excel से इन फ़ील्ड को कई आउटपुट में जनरेट करें।</div>",
  "Select from your panel's product library; name, price, image and attributes will fill the fields automatically.": "अपने पैनल की उत्पाद लाइब्रेरी से चयन करें; नाम, मूल्य, छवि और विशेषताएँ फ़ील्ड स्वचालित रूप से भर जाएंगी।",
