  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>पहले डिज़ाइन (दाएं पैनल) में कम से कम एक ऑब्जेक्ट के लिए एक डिज़ाइन फ़ील्ड निर्दिष्ट करें, फिर AI उन्हें भर देगा।</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "यह अनुरोध बल्क बिल्डर (पीएलएएन पास) से आता है। निर्देश और डिज़ाइन फ़ील्ड पढ़ें, फिर आपके द्वारा उत्पादित आउटपुट को सूचीबद्ध करें, केवल लेबल करें (कोई फ़ील्ड सामग्री नहीं)। केवल एक कच्चा JSON ऑब्जेक्ट लौटाएँ: {\"अनुवाद\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"लेबल\": [ ... ]}। जब अनुवाद सही होता है तो लेबल भाषा के नाम होते हैं (उसी भाषा में लिखे जाते हैं जिसे उपयोगकर्ता ने इस्तेमाल किया था)। अन्यथा लेबल प्रति आउटपुट एक विशिष्ट संक्षिप्त विषय/बीज हैं। निर्देश में निर्दिष्ट किसी भी मात्रा का सम्मान करें; अन्यथा एक समझदार सेट (लगभग 6 से 12)। हार्ड कैप 500.\n",
