  "<button class=\"sbtn\" id=\"bs-ed-cancel\" style=\"padding:10px 24px;width:auto;height:auto;font-size:13px;background:var(--surface2);color:var(--text-dim)\">Cancel</button>": "<button class=\"sbtn\" id=\"bs-ed-cancel\" style=\"padding:10px 24px;width:auto;height:auto;font-size:13px;background:var(--surface2);color:var(--text-dim)\">रद्द करें</button>",
