  "<div class=\"settings-section-title\">Page Sleep</div><div class=\"settings-form\"><p style=\"font-size:12px;color:var(--text-dim)\">Sleep module not loaded.</p></div>": "<div class=\"settings-section-title\">पेज स्लीप</div><div class=\"settings-form\"><p style=\"font-size:12px;color:var(--text-dim)\">स्लीप मॉड्यूल लोड नहीं हुआ।</p></div>",
  "<p style=\"font-size:12px;color:var(--text-dim);line-height:1.55;margin:0\">": "<p style=\"font-size:12px;color:var(--text-dim);line-height:1.55;margin:0\">",
