  "<p style=\"font-size:11px;color:var(--text-dim);margin:12px 0 6px\">Maximum awake pages <span style=\"color:var(--text-faint)\">(pages older than this number sleep)</span></p>": "<p style=\"font-size:11px;color:var(--text-dim);margin:12px 0 6px\">अधिकतम सक्रिय पेज <span style=\"color:var(--text-faint)\">(इस संख्या से पुराने पेज स्लीप में चले जाते हैं)</span></p>",
  "<p style=\"font-size:11px;color:var(--text-dim);margin:14px 0 6px\">Neighbor window <span style=\"color:var(--text-faint)\">(pages kept awake on each side of the active page)</span></p>": "<p style=\"font-size:11px;color:var(--text-dim);margin:14px 0 6px\">पड़ोसी विंडो <span style=\"color:var(--text-faint)\">(सक्रिय पेज के दोनों ओर सक्रिय रखे जाने वाले पेज)</span></p>",
  "<div class=\"ps-stat\"><div class=\"ps-stat-num\" style=\"color:var(--gold)\">": "<div class=\"ps-stat\"><div class=\"ps-stat-num\" style=\"color:var(--gold)\">",
  "settings: sleep": "सेटिंग्स: नींद",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">इस ब्राउज़र से समय की स्वतः बचत करें। नवीनतम स्थिति <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span> के अंतर्गत संग्रहीत है; रोलिंग स्नैपशॉट <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p> का उपयोग करते हैं",
  "<div style=\"font-size:14px;color:var(--text)\">": "<div style=\"font-size:14px;color:var(--text)\">",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">अभी कोई <code>dika_autosave</code> एंट्री नहीं है।</p>",
  "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">": "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">",
  " — <span style=\"color:var(--text-faint)\">": " — <span style=\"color:var(--text-faint)\">",
  "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">No rolling snapshots yet (they are added on each auto-save tick).</p>": "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">अभी कोई रोलिंग स्नैपशॉट नहीं है; हर ऑटो-सेव पर जोड़ा जाता है।</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">सेव किए गए वर्ज़न स्नैपशॉट साफ़ करता है (<code>dika_versions</code>)। मौजूदा कैनवास और सबसे नई ऑटो-सेव फ़ाइल हटाई नहीं जाती।</span>",
