  "Team data is only kept for cloud-backed projects opened from the panel. Save this design and the per-collaborator breakdown shows up here.": "टीम डेटा केवल पैनल से खोले गए क्लाउड-समर्थित प्रोजेक्ट के लिए रखा जाता है। इस डिज़ाइन को सहेजें और प्रति-सहयोगी विवरण यहां दिखाई देगा।",
