  "No folders yet. Click the button above to create one.": "अभी तक कोई फ़ोल्डर नहीं. एक बनाने के लिए ऊपर दिए गए बटन पर क्लिक करें।",
  "No images uploaded yet.": "अभी तक कोई चित्र अपलोड नहीं किया गया.",
  "Products, categories, brands and attributes come from the dika studio product catalogue.": "उत्पाद, श्रेणियाँ, ब्रांड और विशेषताएँ dika studio उत्पाद कैटलॉग से आती हैं।",
  "This is the offline Community Edition, so there is no catalogue to read from.": "यह ऑफ़लाइन सामुदायिक संस्करण है, इसलिए पढ़ने के लिए कोई कैटलॉग नहीं है।",
