  "A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.": "नया पेज व्हाइटबोर्ड के रूप में खुलेगा। पूरे कैनवास पर स्वतंत्र रूप से ड्रॉ करें और शेप, स्टिकी नोट व कनेक्टर जोड़ें।",
